(function(){const S='nlp_sid',E='https://noetic-presence.mselayet.workers.dev',I=3e4;let s=localStorage.getItem(S);if(!s){s='v_'+Date.now().toString(36)+Math.random().toString(36).substr(2,9);localStorage.setItem(S,s)}const h=()=>{const d={sessionId:s,page:location.pathname,referrer:document.referrer};fetch(E+'/presence/heartbeat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d),keepalive:true}).catch(()=>{})};h();setInterval(h,I);const l=()=>{navigator.sendBeacon(E+'/presence/leave',JSON.stringify({sessionId:s}))};window.addEventListener('beforeunload',l);document.addEventListener('visibilitychange',()=>{if(document.hidden)l();else h()})})();
